W = 3
I, R = "Inkoop", "Recht"

# ---------- Inkoop MC ----------
mc("ir3-i01", W, I, "Wat is het doel van Europees aanbesteden volgens de slides?",
   ["Inkopers in de publieke sector meer vrijheid geven", "Marktwerking: de markt openstellen voor alle bedrijven in de EU, zodat iedereen een eerlijke kans krijgt", "Nederlandse bedrijven voorrang geven bij overheidsopdrachten", "De administratieve lasten voor leveranciers verhogen"], 1,
   "Europees aanbesteden opent de markt voor alle bedrijven in de EU, ongeacht waar ze gevestigd zijn. Het vloeit voort uit het GPA-verdrag van de Wereldhandelsorganisatie.")
mc("ir3-i02", W, I, "Op welke fase van het inkoopproces heeft een aanbesteding vooral betrekking?",
   ["De strategische fase", "De tactische inkoopfase: specificeren, selecteren en contracteren", "De operationele fase: bestellen en bewaken", "De nazorgfase"], 1,
   "De aanbesteding gaat over de tactische inkoopfase van het inkoopproces: van specificeren tot het sluiten van het contract.")
